WITH deleted_push_tokens AS (
  DELETE FROM user_push_tokens WHERE user_id = #{userId} RETURNING 1
),
deleted_notification_preferences AS (
  DELETE FROM user_notification_preferences WHERE user_id = #{userId} RETURNING 1
),
deleted_chat_mutes AS (
  DELETE FROM chat_notification_mutes WHERE user_id = #{userId} RETURNING 1
),
deleted_feed_blocks AS (
  DELETE FROM user_feed_blocks WHERE user_id = #{userId} RETURNING 1
)
DELETE FROM friend_requests WHERE requester_user_id = #{userId} OR recipient_user_id = #{userId};
